import random
import code_test

# participants_exte = {nom : nb_ticket}
participants_cs = code_test.load_participants_cs()
participants_exte = {}
lots = ['PS5', 'Casque Sony', 'enceinte JBL', "ticket d'or wei", "ticket d'or wei", 'appareils à raclette', 'appareils à raclette', 'bouteille de vin', 'bouteille de vin', 'bouteille de vin', 'place au TOSS', 'place Grape', 'place Grape', 'date bistrot', 'date bistrot', 'menu M', 'menu M', 'menu M', 'menu M', 'menu M', 'place commus', 'place commus', 'place commus', 'place commus', 'place commus', 'culottes menstruelles', 'culottes menstruelles', '1 cup', 'livre', 'livre', 'livre', 'livre', 'livre', 'livre', 'livre', 'livre', 'livre', 'livre']
lots_cs = []
def tirage_tombola_cs():
    # TIRAGE DES LOTS DES ETUDIANTS DE CS 
    gagnants = {}
    tickets_cs = []
    tickets = []
    for nom, nb in participants_cs.items():        
        tickets_cs += [nom]*nb
    for nom, nb in participants_cs.items():        
        tickets += [nom]*nb
    for nom, nb in participants_exte.items():
        tickets += [nom]*nb
        
    for i in range (len(lots)):
        e= lots[i]
        if e in lots_cs:
            if not tickets_cs:
                # Pas de ticket CS disponible -> log et passer au lot suivant
                print(f"Aucun ticket CS disponible pour le lot '{e}' (index {i}). Lot ignoré.")
                continue
            gagnant = random.choice(tickets_cs)
            tickets_cs = [n for n in tickets_cs if n != gagnant]
            gagnants[gagnant] = e
        else:
            if not tickets:
                print(f"Aucun ticket restant — {len(lots) - i} lots non attribués.")
                break
            gagnant = random.choice(tickets)
            tickets = [n for n in tickets if n != gagnant]
            gagnants[gagnant] = e
    return gagnants 


print(tirage_tombola_cs())
    
